 93→  const shop = session.shop;
 94→
 95→  const [zipCodes, subscription] = await Promise.all([
 96→    db.zipCode.findMany({
 97→      where: { shop },
 98→      orderBy: { createdAt: "desc" },
 99→    }),
100→    getShopSubscription(shop),

100→    getShopSubscription(shop),
