113→export const action = async ({ request }: ActionFunctionArgs) => {
114→  const { session } = await authenticate.admin(request);
115→  const shop = session.shop;
116→  const formData = await request.formData();
117→  const intent = formData.get("intent");
118→
119→  if (intent === "add") {
120→    const zipCode = String(formData.get("zipCode")).trim().toUpperCase();
121→    const label = String(formData.get("label") || "").trim();
122→    const zone = String(formData.get("zone") || "").trim();
123→    const message = String(formData.get("message") || "").trim();
124→    const eta = String(formData.get("eta") || "").trim();
125→    const type = String(formData.get("type") || "allowed");
126→    const codAvailable =
127→      formData.get("codAvailable") === "true"
128→        ? true
129→        : formData.get("codAvailable") === "false"
130→          ? false
131→          : null;
132→    const returnPolicy = (formData.get("returnPolicy") as string | null) || null;
133→
134→    if (!zipCode) return { error: "Zip code is required." };
135→
136→    const subscription = await getShopSubscription(shop);
137→    const limits = PLAN_LIMITS[subscription.planTier];
138→
139→    if (type === "blocked" && !limits.allowBlocked) {
140→      return {
141→        error:
142→          "Blocked zip codes are not available on your current plan. Upgrade to Pro or Ultimate to use blocked zip codes.",
143→        upgradeRequired: true,
144→      };
145→    }
146→
147→    const currentCount = await db.zipCode.count({ where: { shop } });
148→    if (limits.maxZipCodes < UNLIMITED && currentCount >= limits.maxZipCodes) {
149→      const upgradeTarget =
150→        subscription.planTier === "free" ? "Starter" : "Pro";
151→      return {
152→        error: `You have reached the ${limits.maxZipCodes} zip code limit on the ${limits.label} plan. Upgrade to ${upgradeTarget} for a higher limit.`,
153→        upgradeRequired: true,
154→      };
155→    }
156→
157→    try {
158→      await db.zipCode.create({
159→        data: {
160→          shop,
161→          zipCode,
162→          label: label || null,
163→          zone: zone || null,
164→          message: message || null,
165→          eta: eta || null,
166→          type,
167→          codAvailable: codAvailable ?? undefined,
168→          returnPolicy: returnPolicy ?? undefined,
169→        },
170→      });
171→      return { success: true, action: "added", zipCode };
172→    } catch {
173→      return { error: `Zip code "${zipCode}" already exists.` };
174→    }
175→  }
176→
177→  if (intent === "delete") {
178→    const id = String(formData.get("id"));
179→    try {
180→      const existing = await db.zipCode.findFirst({ where: { id, shop } });
181→      if (!existing) return { error: "Zip code not found." };
182→      await db.zipCode.delete({ where: { id } });
183→      return { success: true, action: "deleted" };
184→    } catch {
185→      return { error: "Failed to delete zip code." };
186→    }
187→  }
188→
189→  if (intent === "update") {
190→    const id = String(formData.get("id"));
191→    const zipCode = String(formData.get("zipCode")).trim().toUpperCase();
192→    const label = String(formData.get("label") || "").trim();
193→    const zone = String(formData.get("zone") || "").trim();
194→    const message = String(formData.get("message") || "").trim();
195→    const eta = String(formData.get("eta") || "").trim();
196→    const type = String(formData.get("type") || "allowed");
197→    const isActive = formData.get("isActive") === "true";
198→    const codAvailable =
199→      formData.get("codAvailable") === "true"
200→        ? true
201→        : formData.get("codAvailable") === "false"
202→          ? false
203→          : null;
204→    const returnPolicy = (formData.get("returnPolicy") as string | null) || null;
205→
206→    if (!zipCode) return { error: "Zip code is required." };
207→
208→    try {
209→      const existing = await db.zipCode.findFirst({ where: { id, shop } });
210→      if (!existing) return { error: "Zip code not found." };
211→      await db.zipCode.update({
212→        where: { id },
213→        data: {
214→          zipCode,
215→          label: label || null,
216→          zone: zone || null,
217→          message: message || null,
218→          eta: eta || null,
219→          type,
220→          isActive,
221→          codAvailable,
222→          returnPolicy,
223→        },
224→      });
225→      return { success: true, action: "updated", zipCode };
226→    } catch {
227→      return { error: `Failed to update zip code "${zipCode}". It may already exist.` };
228→    }
229→  }
230→
231→  if (intent === "toggle") {
232→    const id = String(formData.get("id"));
233→    const isActive = formData.get("isActive") === "true";
234→    try {
235→      const existing = await db.zipCode.findFirst({ where: { id, shop } });
236→      if (!existing) return { error: "Zip code not found." };
237→      await db.zipCode.update({
238→        where: { id },
239→        data: { isActive: !isActive },
240→      });
241→      return { success: true, action: "toggled" };
242→    } catch {
243→      return { error: "Failed to toggle zip code status." };
244→    }
245→  }
246→
247→  if (intent === "check") {
248→    const zipCode = String(formData.get("checkZip")).trim().toUpperCase();
249→    try {

250→      const found = await db.zipCode.findUnique({
251→        where: { shop_zipCode: { shop, zipCode } },
252→      });
253→      if (!found) return { checkResult: { found: false, zipCode } };
254→      return { checkResult: { found: true, zipCode, record: found } };
255→    } catch {
256→      return { error: "Failed to check zip code." };
257→    }
258→  }
259→
260→  if (intent === "bulk-import") {
261→    const csvData = String(formData.get("csvData") || "");
262→    if (!csvData.trim()) return { error: "No CSV data provided." };
263→
264→    const subscription = await getShopSubscription(shop);
265→    const limits = PLAN_LIMITS[subscription.planTier];
266→
267→    if (!limits.csvImport) {
268→      const upgradeTarget =
269→        subscription.planTier === "free" ? "Starter" : "Pro";
270→      return {
271→        error: `CSV import is not available on the ${limits.label} plan. Upgrade to ${upgradeTarget} to import zip codes via CSV.`,
272→        upgradeRequired: true,
273→      };
274→    }
275→
276→    const lines = csvData
277→      .split("\n")
278→      .map((l) => l.trim())
279→      .filter((l) => l.length > 0);
280→
281→    // Skip header row if present
282→    const startIdx =
283→      lines.length > 0 &&
284→      lines[0].toLowerCase().includes("zip")
285→        ? 1
286→        : 0;
287→
288→    const currentCount = await db.zipCode.count({ where: { shop } });
289→    let imported = 0;
290→    let skipped = 0;
291→    const errors: string[] = [];
292→
293→    for (let i = startIdx; i < lines.length; i++) {
294→      const cols = parseCsvRow(lines[i]);
295→      const zipCode = (cols[0] || "").toUpperCase();
296→      if (!zipCode) continue;
297→
298→      const zone = cols[1] || null;
299→      const type = (cols[2] || "allowed").toLowerCase() === "blocked" ? "blocked" : "allowed";
300→      const message = cols[3] || null;
301→      const eta = cols[4] || null;
302→      const codRaw = (cols[5] || "").toLowerCase().trim();
303→      const codAvailable =
304→        codRaw === "yes" || codRaw === "true"
305→          ? true
306→          : codRaw === "no" || codRaw === "false"
307→            ? false
308→            : null;
309→      const returnPolicy = cols[6] || null;
310→
311→      if (type === "blocked" && !limits.allowBlocked) {
312→        skipped++;
313→        continue;
314→      }
315→
316→      if (
317→        limits.maxZipCodes < UNLIMITED &&
318→        currentCount + imported >= limits.maxZipCodes
319→      ) {
320→        const upgradeTarget =
321→          subscription.planTier === "free" ? "Starter" : "Pro";
322→        errors.push(
323→          `Reached the ${limits.maxZipCodes} zip code limit on the ${limits.label} plan. Upgrade to ${upgradeTarget} for a higher limit. ${lines.length - startIdx - imported - skipped} zip codes were not imported.`,
324→        );
325→        break;
326→      }
327→
328→      try {
329→        await db.zipCode.upsert({
330→          where: { shop_zipCode: { shop, zipCode } },
331→          create: {
332→            shop,
333→            zipCode,
334→            zone,
335→            type,
336→            message,
337→            eta,
338→            codAvailable,
339→            returnPolicy,
340→          },
341→          update: {
342→            zone: zone ?? undefined,
343→            type,
344→            message: message ?? undefined,
345→            eta: eta ?? undefined,
346→            codAvailable,
347→            returnPolicy: returnPolicy ?? undefined,
348→          },
349→        });
350→        imported++;
351→      } catch {
352→        skipped++;
353→      }
354→    }
355→
356→    return {
357→      success: true,
358→      action: "bulk-import",
359→      imported,
360→      skipped,
361→      errors,
362→    };
363→  }
364→
365→  if (intent === "export") {
366→    const subscription = await getShopSubscription(shop);
367→    const limits = PLAN_LIMITS[subscription.planTier];
368→
369→    if (!limits.csvExport) {
370→      return {
371→        error: `CSV export is not available on the ${limits.label} plan. Upgrade to Pro or Ultimate to export your zip codes.`,
372→        upgradeRequired: true,
373→      };
374→    }
375→
376→    try {
377→      const zipCodes = await db.zipCode.findMany({
378→        where: { shop },
379→        orderBy: { createdAt: "desc" },
380→      });
381→
382→      const header = "Zip Code,Zone,Status,Message,ETA,Active,COD,Return Policy";
383→      const rows = zipCodes.map(
384→        (z) =>
385→          `"${z.zipCode}","${z.zone || ""}","${z.type}","${z.message || ""}","${z.eta || ""}","${z.isActive ? "Yes" : "No"}","${z.codAvailable === true ? "Yes" : z.codAvailable === false ? "No" : ""}","${z.returnPolicy || ""}"`,
386→      );
387→      const csv = [header, ...rows].join("\n");
388→
389→      return { success: true, action: "export", csv };
390→    } catch {
391→      return { error: "Failed to export zip codes." };
392→    }
393→  }
394→
395→  if (intent === "range-import") {
396→    const startZip = String(formData.get("startZip") || "").trim().toUpperCase();
397→    const endZip = String(formData.get("endZip") || "").trim().toUpperCase();
398→    const zone = (formData.get("zone") as string | null) || null;
399→    const type = (formData.get("type") as string) === "blocked" ? "blocked" : "allowed";

400→    const message = (formData.get("message") as string | null) || null;
401→    const eta = (formData.get("eta") as string | null) || null;
402→
403→    // Validate: must be 5-digit numeric zips
404→    const ZIP_RE = /^\d{5}$/;
405→    if (!ZIP_RE.test(startZip) || !ZIP_RE.test(endZip)) {
406→      return { error: "ZIP range import only supports 5-digit US ZIP codes (e.g., 10001)." };
407→    }
408→
409→    const start = parseInt(startZip, 10);
410→    const end = parseInt(endZip, 10);
411→
412→    if (end < start) {
413→      return { error: "End ZIP must be greater than or equal to Start ZIP." };
414→    }
415→
416→    const rangeSize = end - start + 1;
417→    const MAX_RANGE = 500;
418→    if (rangeSize > MAX_RANGE) {
419→      return { error: `Range too large. Maximum ${MAX_RANGE} zip codes per import (got ${rangeSize}).` };
420→    }
421→
422→    // Check plan limits
423→    const subscription = await getShopSubscription(shop);
424→    const limits = PLAN_LIMITS[subscription.planTier];
425→
426→    if (!limits.csvImport) {
427→      const upgradeTarget =
428→        subscription.planTier === "free" ? "Starter" : "Pro";
429→      return {
430→        error: `ZIP range import is not available on the ${limits.label} plan. Upgrade to ${upgradeTarget} to use bulk import features.`,
431→        upgradeRequired: true,
432→      };
433→    }
434→
435→    if (type === "blocked" && !limits.allowBlocked) {
436→      return {
437→        error: "Blocked zip codes are not available on your current plan. Upgrade to Pro or Ultimate to use blocked zip codes.",
438→        upgradeRequired: true,
439→      };
440→    }
441→
442→    const currentCount = await db.zipCode.count({ where: { shop } });
443→    if (limits.maxZipCodes < UNLIMITED && currentCount + rangeSize > limits.maxZipCodes) {
444→      const upgradeTarget =
445→        subscription.planTier === "free" ? "Starter" : "Pro";
446→      return {
447→        error: `This range would exceed your ${limits.label} plan limit of ${limits.maxZipCodes} zip codes. You have ${limits.maxZipCodes - currentCount} slots remaining. Upgrade to ${upgradeTarget} for a higher limit.`,
448→        upgradeRequired: true,
449→      };
450→    }
451→
452→    // Generate and upsert all zips in range
453→    let imported = 0;
454→    for (let i = start; i <= end; i++) {
455→      const zipCode = String(i).padStart(5, "0");
456→      try {
457→        await db.zipCode.upsert({
458→          where: { shop_zipCode: { shop, zipCode } },
459→          create: { shop, zipCode, zone: zone ?? undefined, type, message: message ?? undefined, eta: eta ?? undefined },
460→          update: { zone: zone ?? undefined, type, message: message ?? undefined, eta: eta ?? undefined },
461→        });
462→        imported++;
463→      } catch {
464→        // skip individual errors
465→      }
466→    }
467→
468→    return { success: true, action: "range-import", imported, total: rangeSize };
469→  }
470→
471→  return null;
472→};
