489→  const { zipCodes, stats, subscription } = useLoaderData<typeof loader>();
490→  const fetcher = useFetcher<typeof action>();
491→  const shopify = useAppBridge();
492→  const navigate = useNavigate();
493→  const downloadedCsvRef = useRef<string | null>(null);
494→
495→  const limits = PLAN_LIMITS[subscription.planTier];
496→  const isFreePlan = subscription.planTier === "free";
497→  const isStarterPlan = subscription.planTier === "starter";
498→  const atZipLimit =
499→    limits.maxZipCodes < UNLIMITED && stats.total >= limits.maxZipCodes;
500→
501→  // Search & filter state
502→  const [searchQuery, setSearchQuery] = useState("");
503→  const [statusFilter, setStatusFilter] = useState("all");
504→  const [currentPage, setCurrentPage] = useState(1);
505→
506→  // Check zip code state
507→  const [checkZip, setCheckZip] = useState("");
508→
509→  // Add modal state
510→  const [addModalOpen, setAddModalOpen] = useState(false);
511→  const [newZip, setNewZip] = useState("");
