517→  const [newCodAvailable, setNewCodAvailable] = useState(""); // "", "true", "false"
518→  const [newReturnPolicy, setNewReturnPolicy] = useState("");
519→
520→  // Edit modal state
521→  const [editModalOpen, setEditModalOpen] = useState(false);
522→  const [editId, setEditId] = useState("");
523→  const [editZip, setEditZip] = useState("");
524→  const [editLabel, setEditLabel] = useState("");
525→  const [editZone, setEditZone] = useState("");
526→  const [editMessage, setEditMessage] = useState("");
527→  const [editEta, setEditEta] = useState("");
528→  const [editType, setEditType] = useState("allowed");
529→  const [editIsActive, setEditIsActive] = useState(true);
530→  const [editCodAvailable, setEditCodAvailable] = useState(""); // "", "true", "false"
531→  const [editReturnPolicy, setEditReturnPolicy] = useState("");
532→
533→  // Import modal state
534→  const [importModalOpen, setImportModalOpen] = useState(false);
535→  const [csvText, setCsvText] = useState("");
536→  const [importFile, setImportFile] = useState<File | null>(null);
537→
538→  // Range import modal state
539→  const [rangeModalOpen, setRangeModalOpen] = useState(false);
540→  const [rangeStart, setRangeStart] = useState("");
541→  const [rangeEnd, setRangeEnd] = useState("");
542→  const [rangeZone, setRangeZone] = useState("");
543→  const [rangeType, setRangeType] = useState("allowed");
544→  const [rangeMessage, setRangeMessage] = useState("");
545→  const [rangeEta, setRangeEta] = useState("");
546→
547→  const isCheckLoading =
548→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "check";
549→  const isAddLoading =

550→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "add";
551→  const isEditLoading =
552→    fetcher.state !== "idle" && fetcher.formData?.get("intent") === "update";
553→  const isImportLoading =
554→    fetcher.state !== "idle" &&
555→    fetcher.formData?.get("intent") === "bulk-import";
556→
557→  const checkResult =
558→    fetcher.data && "checkResult" in fetcher.data
559→      ? fetcher.data.checkResult
560→      : null;
561→  const actionError =
562→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
563→  const upgradeRequired =
564→    fetcher.data && "upgradeRequired" in fetcher.data
565→      ? fetcher.data.upgradeRequired
566→      : false;
567→  const importResult =
568→    fetcher.data &&
569→    "action" in fetcher.data &&
570→    fetcher.data.action === "bulk-import"
571→      ? fetcher.data
572→      : null;
573→
574→  const rangeResult =
575→    fetcher.data &&
576→    "action" in fetcher.data &&
577→    fetcher.data.action === "range-import"
578→      ? fetcher.data
579→      : null;
580→
581→  const isRangeLoading =
582→    fetcher.state !== "idle" &&
583→    fetcher.formData?.get("intent") === "range-import";
584→
585→  // Filtered zip codes
586→  const filteredZipCodes = useMemo(() => {
587→    let filtered = zipCodes as ZipCodeRecord[];
588→
589→    if (searchQuery.trim()) {
590→      const q = searchQuery.trim().toLowerCase();
591→      filtered = filtered.filter(
592→        (z) =>
593→          z.zipCode.toLowerCase().includes(q) ||
594→          (z.zone && z.zone.toLowerCase().includes(q)) ||
595→          (z.label && z.label.toLowerCase().includes(q)) ||
596→          (z.message && z.message.toLowerCase().includes(q)),
597→      );
