599→
600→    if (statusFilter === "allowed") {
601→      filtered = filtered.filter((z) => z.type === "allowed");
602→    } else if (statusFilter === "blocked") {
603→      filtered = filtered.filter((z) => z.type === "blocked");
604→    }
605→
606→    return filtered;
607→  }, [zipCodes, searchQuery, statusFilter]);
608→
609→  // Pagination
610→  const totalPages = Math.max(1, Math.ceil(filteredZipCodes.length / PAGE_SIZE));
611→  const paginatedZipCodes = useMemo(() => {
612→    const start = (currentPage - 1) * PAGE_SIZE;
613→    return filteredZipCodes.slice(start, start + PAGE_SIZE);
